-- 26.9.22 사장님 결정: 창작(heavy) 모델도 딥시크로(블라인드 평가에서 딥시크 새 엔진이 하이쿠보다 나았고 원가 1/25).
-- 되돌리기용 원래 값:
-- {"pro": {"primary": "claude-sonnet-5", "fallback": "claude-haiku-4-5"}, "free": {"primary": "deepseek-chat", "fallback": "deepseek-chat"}, "lite": {"primary": "claude-haiku-4-5", "fallback": "deepseek-chat"}, "guest": {"primary": "deepseek-chat", "fallback": "deepseek-chat"}, "friend": {"primary": "claude-haiku-4-5", "fallback": "deepseek-chat"}, "companion_plus": {"primary": "claude-haiku-4-5", "fallback": "deepseek-chat"}, "companion_soul": {"primary": "claude-sonnet-5", "fallback": "claude-haiku-4-5"}, "companion_daily": {"primary": "claude-haiku-4-5", "fallback": "deepseek-chat"}, "companion_always": {"primary": "claude-sonnet-5", "fallback": "claude-haiku-4-5"}, "companion_sometimes": {"primary": "claude-haiku-4-5", "fallback": "deepseek-chat"}}
update app_settings set v = jsonb_set(v, '{models,heavy}', (select jsonb_object_agg(k, jsonb_build_object('primary','deepseek-reasoner','fallback','deepseek-chat')) from jsonb_object_keys(v->'models'->'heavy') k)) where k='ai_margin';
